<script setup lang="ts">
import {nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {prepareAnimation,decodeAnimation,type AnimationAsset} from './media';
import {animationRepository} from './repository';
import AnimationPlayer from './AnimationPlayer.vue';
const previewButton=ref<HTMLButtonElement>(),previewClose=ref<HTMLButtonElement>();
const asset=ref<AnimationAsset|null>(null),busy=ref(false),error=ref(''),notice=ref(''),preview=ref(false),readFailed=ref(false);let alive=true,generation=0;
onMounted(async()=>{try{const saved=await animationRepository.read();if(alive&&generation===0)asset.value=saved;}catch(e){if(alive&&generation===0){readFailed.value=true;error.value=(e as Error).message;}}});onBeforeUnmount(()=>{alive=false;++generation;document.removeEventListener('keydown',previewKey,true);});
function previewKey(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();preview.value=false;}else if(e.key==='Tab'){e.preventDefault();previewClose.value?.focus();}}
watch(preview,async open=>{if(open)document.addEventListener('keydown',previewKey,true);else document.removeEventListener('keydown',previewKey,true);await nextTick();if(alive)(open?previewClose:previewButton).value?.focus();});
async function selected(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||busy.value)return;busy.value=true;error.value='';notice.value='';const attempt=++generation;
 try{const candidate=await prepareAnimation(file);await decodeAnimation(candidate);if(!alive||attempt!==generation)return;await animationRepository.write(candidate);if(alive){asset.value=candidate;readFailed.value=false;notice.value='已保存，将在下次启用开屏时显示。';}}catch(e){if(alive)error.value=(e as Error).message;}finally{if(alive)busy.value=false;}}
async function reset(){if(busy.value)return;++generation;busy.value=true;error.value='';try{await animationRepository.clear();if(alive){asset.value=null;readFailed.value=false;notice.value='已恢复默认短动画；开屏总开关保持原设置。';preview.value=false;}}catch(e){if(alive)error.value=(e as Error).message;}finally{if(alive)busy.value=false;}}
</script>
<template><section class="animation-settings" aria-label="自定义开屏设置"><h3>我的开屏动画</h3><p>{{asset?asset.name+' · '+(asset.blob.size/1024/1024).toFixed(1)+'MiB':'使用默认短动画'}}</p><p class="launcher-caption">GIF、MP4、WebM，最多30MiB。仅本机保存、静音播放，最多8秒，可随时跳过。清理窗口数据会清除导入素材。</p><div class="animation-actions"><label class="launcher-secondary animation-import">{{busy?'正在检查…':'导入动画'}}<input data-import-intro type="file" accept=".gif,.mp4,.webm,image/gif,video/mp4,video/webm" :disabled="busy" @change="selected"></label><button ref="previewButton" class="launcher-secondary" data-preview-custom-intro :disabled="busy||!asset" @click="preview=true">预览</button><button class="launcher-secondary" data-restore-intro :disabled="busy||(!asset&&!readFailed)" @click="reset">恢复默认</button></div><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><Teleport to=".launcher-shell"><div v-if="preview&&asset" class="workspace-intro custom-intro-preview" data-custom-intro-preview role="dialog" aria-modal="true" aria-label="自定义开屏预览"><AnimationPlayer :asset="asset" @finished="preview=false" @failed="error='动画播放失败，可恢复默认或重新导入。'"/><button ref="previewClose" @click="preview=false">结束预览</button></div></Teleport></section></template>
<style scoped>.animation-actions{display:flex;gap:12px;flex-wrap:wrap}.custom-intro-preview{z-index:1900}.animation-settings{margin-top:24px}.animation-settings p{line-height:1.7}.animation-import{position:relative;overflow:hidden;cursor:pointer}.animation-import input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}</style>
